const aplicadas = new Set<string>();

/**
 * Troca, no próprio dicionário, o espanhol de cada entrada que tem linha aqui.
 *
 * Substitui o objeto da entrada em vez de alterá-lo: as entradas que vêm de
 * outro módulo por espalhamento (`...TEXTOS_AGENDA_SERVICOS`) são as mesmas
 * referências do módulo de origem, e este não deve mudar por tabela.
 */
export function aplicarEspanholDeUsted(dicionario: Record<string, Linha>): void {
  for (const [chave, linha] of Object.entries(dicionario)) {
    const es = linha.es;
    if (es === undefined || !Object.hasOwn(ESPANHOL_DE_USTED, es)) continue;
    dicionario[chave] = { ...linha, es: ESPANHOL_DE_USTED[es] };
    aplicadas.add(es);
  }
}

/** As linhas daqui que não casaram com nenhuma entrada: a upstream mudou ou tirou aquele texto. */
export function linhasDeUstedSemUso(): string[] {
  return Object.keys(ESPANHOL_DE_USTED).filter((tu) => !aplicadas.has(tu));
}
